		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		oldp := vv[newp.LangIndex()]
		if oldp != newp {
			resource.MarkStale(oldp)
		}
		vv[newp.LangIndex()] = newp
		return vv, oldp, oldp != nil
	default:
		panic(fmt.Sprintf("unknown type %T", old))
	}
}

